head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil35604";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil35604.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((String(String(dma_disclosureSchedule.get("calndDd")) === null ? '' : String(dma_disclosureSchedule.get("calndDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(dma_disclosureSchedule.get("calndDd")).slice(0,4)).replace(/MM/g, String(dma_disclosureSchedule.get("calndDd")).slice(4,6)).replace(/dd/g, String(dma_disclosureSchedule.get("calndDd")).slice(6,8)).replace(/HH/g, String(dma_disclosureSchedule.get("calndDd")).slice(8,10)).replace(/mm/g, String(dma_disclosureSchedule.get("calndDd")).slice(10,12)).replace(/ss/g, String(dma_disclosureSchedule.get("calndDd")).slice(12,14)))); } },
        { childId: "btn_Disclsviewer", fn: function () { return String(dma_disclosureSchedule.get("schdlContn")); } },
        { childId: "__rb2", fn: function () { return String((String(String(dma_disclosureSchedule.get("preCalndDd")) === null ? '' : String(dma_disclosureSchedule.get("preCalndDd"))) === '' ? '' : String("yyyy-MM-dd hh:mm").replace(/yyyy/g, String(dma_disclosureSchedule.get("preCalndDd")).slice(0,4)).replace(/MM/g, String(dma_disclosureSchedule.get("preCalndDd")).slice(4,6)).replace(/dd/g, String(dma_disclosureSchedule.get("preCalndDd")).slice(6,8)).replace(/HH/g, String(dma_disclosureSchedule.get("preCalndDd")).slice(8,10)).replace(/mm/g, String(dma_disclosureSchedule.get("preCalndDd")).slice(10,12)).replace(/ss/g, String(dma_disclosureSchedule.get("preCalndDd")).slice(12,14)))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Disclsviewer_onclick
 * @description btn_Disclsviewer 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Disclsviewer_onclick = function(e){
    try {
        scwin.disclsviewer('' + dma_disclosureSchedule.get("acptNo") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35604.btn_Disclsviewer_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e){
    try {
        scwin.close(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35604.btn_Close_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name disclsviewer
 * @description disclsviewer 처리
 * @param {*} _acptNo _acptNo
 * @returns {void}
 * @hidden N
 */
scwin.disclsviewer = function (_acptNo) {
    const viewerUrl = "/submission/disclosureView.do?acptNo=" + _acptNo;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(viewerUrl), { id: "viewer", scrollbars: true, resizable: false, width: "1020", height: "700", type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
